  assign read_allow  = RD_EN & ~ll_afifo_empty;
  always @(posedge WR_CLK or posedge WR_RST) begin
    if (WR_RST)
      wr_pntr_ll_afifo   <= 0;
    else if (write_allow)
      wr_pntr_ll_afifo <= #`TCQ wr_pntr_ll_afifo + 1;
  end
  always @(posedge RD_CLK or posedge RD_RST) begin
    if (RD_RST)
