            STORAGE_DATA <= 0; 
        end else begin
            if(S_VALID == 1'b1 && S_READY_I == 1'b1 ) begin
                STORAGE_DATA <= S_PAYLOAD_DATA; 
            end
        end
    end
    always @(posedge ACLK) begin
        M_PAYLOAD_DATA <= STORAGE_DATA;
    end
    always @(posedge ACLK or posedge ARESET_D) begin
        if (ARESET_D != 2'b00) begin
            M_VALID_I <= 1'b0; 
